#include <unordered_map>
#include <cstdlib>

using namespace std;

class Solution {
    int m, n, total;
    unordered_map<int, int> map;

public:
    Solution(int m, int n) : m(m), n(n), total(m * n) {}

    vector<int> flip() {
        int r = rand() % total--;
        int x = map.count(r) ? map[r] : r;
        map[r] = map.count(total) ? map[total] : total;
        return {x / n, x % n};
    }

    void reset() {
        map.clear();
        total = m * n;
    }
};
